Aquí está la función en C++ que toma una referencia a un `std::string` que contiene texto con formato Markdown y devuelve un `std::string` que contiene texto con formato HTML:

```cpp
#include <iostream>
#include <string>
#include <regex>

std::string markdown_to_html(const std::string& markdown) {
    std::string html;

    // Reemplaza los enlaces
    std::regex link_regex(R"(\[(.*?)\](\((.*?)\)|\((.*? )\)))");
    std::smatch link_match;

    while (std::regex_search(markdown, link_match, link_regex)) {
        std::string link_text = link_match[1];
        std::string link_url;
        if (link_match[2].matched) {
            link_url = link_match[2];
        } else if (link_match[3].matched) {
            link_url = link_match[3];
        }

        html += "<a href=\"" + link_url + "\">" + link_text + "</a>";
        markdown.erase(link_match.position(), link_match.length());
    }

    // Reemplaza los títulos
    std::regex title_regex(R"(\#{1,6} (.*? )\#*)");
    std::smatch title_match;

    while (std::regex_search(markdown, title_match, title_regex)) {
        std::string title_text = title_match[1];
        int level = title_match[0].length();

        std::string opening_tag = "<h";
        opening_tag += std::to_string(level);
        opening_tag += ">";
        std::string closing_tag = "</h" + std::to_string(level) + ">";

        html += opening_tag + title_text + closing_tag;
        markdown.erase(title_match.position(), title_match.length());
    }

    // Reemplaza los listados
    std::regex list_regex(R"(^(?:\*\s|-\s|\+)\s(.*? )\n?)");
    std::smatch list_match;

    while (std::regex_search(markdown, list_match, list_regex)) {
        std::string list_text = list_match[1];

        std::string opening_tag = "<ul>";
        std::string item_tag = "<li>";
        std::string closing_tag = "</li></ul>";

        if (list_text.front() == '*') {
            opening_tag = "<ul style='list-style-type: disc;'>";
            item_tag = "<li>";
        } else if (list_text.front() == '-') {
            opening_tag = "<ul style='list-style-type: circle;'>";
            item_tag = "<li>";
        } else if (list_text.front() == '+') {
            opening_tag = "<ul style='list-style-type: square;'>";
            item_tag = "<li>";
        }

        html += opening_tag + item_tag + list_text + closing_tag;
        markdown.erase(list_match.position(), list_match.length());
    }

    // Reemplaza los citas
    std::regex quote_regex(R"^(> {0,3}(.*? )\n?)");
    std::smatch quote_match;

    while (std::regex_search(markdown, quote_match, quote_regex)) {
        std::string quote_text = quote_match[1];

        std::string opening_tag = "<blockquote>";
        std::string closing_tag = "</blockquote>";

        for (int I = 0; I < quote_match[0].length() / 4; i++) {
            opening_tag += "<div class='blockquote-indent'>";
            closing_tag = "</div>" + closing_tag;
        }

        html += opening_tag + quote_text + closing_tag;
        markdown.erase(quote_match.position(), quote_match.length());
    }

    // Reemplaza los códigos
    std::regex code_regex(R"(```(.*?)```)");
    std::smatch code_match;

    while (std::regex_search(markdown, code_match, code_regex)) {
        std::string code_text = code_match[1];

        std::string opening_tag = "<pre><code>";
        std::string closing_tag = "</code></pre>";

        html += opening_tag + code_text + closing_tag;
        markdown.erase(code_match.position(), code_match.length());
    }

    // Reemplaza los emojis
    std::regex emoji_regex(R"(:\w+ :)");
    std::smatch emoji_match;

    while (std::regex_search(markdown, emoji_match, emoji_regex)) {
        std::string emoji_text = emoji_match[0].str();
        std::string emoji_html = "<img src='https://cdn.jsdelivr.net/gh/twitter/typeahead.js@master/dist/css/emoji.css' class='emoji' alt='" + emoji_text.substr(1, emoji_text.length() - 2) + "' title='" + emoji_text.substr(1, emoji_text.length() - 2) + "' data-name='" + emoji_text.substr(1, emoji_text.length() - 2) + "' data-emoji=true>";

        html += emoji_html;
        markdown.erase(emoji_match.position(), emoji_match.length());
    }

    // Reemplaza los símbolos de escape
    std::string escape_regex = R"(\\[abfnrtv])";
    std::regex escape_regex_obj(escape_regex);

    std::string::iterator it = markdown.begin();
    while (it != markdown.end()) {
        std::smatch escape_match;
        if (std::regex_search(it, markdown.end(), escape_match, escape_regex_obj)) {
            std::string escape_char = escape_match[0].str();
            std::string escape_html;
            switch (escape_char[1]) {
                case 'a':
                    escape_html = "&aacute;";
                    break;
                case 'b':
                    escape_html = "&bdquo;";
                    break;
                case 'f':
                    escape_html = "&frac14;";
                    break;
                case 'n':
                    escape_html = "&ntilde;";
                    break;
                case 'r':
                    escape_html = "&raquo;";
                    break;
                case 't':
                    escape_html = "&frac12;";
                    break;
                case 'v':
                    escape_html = "&uacute;";
                    break;
            }
            html += escape_html;
            it = escape_match.position() + 1;
        } else {
            html += *it;
            ++it;
        }
    }

    return html;
}

int main() {
    std::string markdown = "Hello, **world**! \n\n This is a [link](https://example.com) and a [link with title](https://example.com 'Title'). \n\n # Heading 1 \n ## Heading 2 \n ### Heading 3 \n #### Heading 4 \n ##### Heading 5 \n ###### Heading 6 \n\n - Item 1 \n - Item 2 \n - Item 3 \n\n > This is a quote. \n\n ```cpp\n int main() {}\n``` \n\n :smile: :heart: :rocket: ";

    std::string html = markdown_to_html(markdown);
    std::cout << html << std::endl;

    return 0;
}
```

Este código implementa las conversiones básicas de Markdown a HTML, incluyendo enlaces, títulos, listados, citas, códigos y emojis. También incluye la conversión de algunos símbolos de escape. Puede ser adaptado y extendido según las necesidades específicas del proyecto.

