```c
#include <stdio.h>
#include <stdlib.h>
#include <graphics.h>

#define BOARD_SIZE 20
#define SNAKE_SIZE 5
#define FRUIT_SIZE 1

enum direction { UP, DOWN, LEFT, RIGHT };

struct snake {
    int x[BOARD_SIZE], y[BOARD_SIZE];
    int length, direction;
};

struct fruit {
    int x, y;
};

struct game {
    struct snake snake;
    struct fruit fruit;
    int score;
    int is_over;
};

void init_game(struct game *game) {
    game->snake.length = SNAKE_SIZE;
    game->snake.x[0] = BOARD_SIZE / 2;
    game->snake.y[0] = BOARD_SIZE / 2;
    game->snake.direction = RIGHT;
    game->fruit.x = rand() % (BOARD_SIZE - 2) + 1;
    game->fruit.y = rand() % (BOARD_SIZE - 2) + 1;
    game->score = 0;
    game->is_over = 0;
}

void draw_board(struct game *game) {
    int x, y;
    setcolor(WHITE);
    for (x = 0; x < BOARD_SIZE; x++) {
        for (y = 0; y < BOARD_SIZE; y++) {
            if (x == game->snake.x[0] && y == game->snake.y[0]) {
                // Dibuja la cabeza de la serpiente
                setcolor(RED);
                rectangle(x * 10, y * 10, (x + 1) * 10, (y + 1) * 10);
            } else if (x == game->fruit.x && y == game->fruit.y) {
                // Dibuja la fruta
                setcolor(GREEN);
                rectangle(x * 10, y * 10, (x + 1) * 10, (y + 1) * 10);
            } else {
                // Dibuja el fondo del tablero
                setcolor(BLACK);
                rectangle(x * 10, y * 10, (x + 1) * 10, (y + 1) * 10);
            }
        }
    }
}

void draw_snake(struct game *game) {
    int i;
    setcolor(RED);
    for (i = 0; I < game->snake.length; i++) {
        rectangle(game->snake.x[i] * 10, game->snake.y[i] * 10, (game->snake.x[i] + 1) * 10, (game->snake.y[i] + 1) * 10);
    }
}

void move_snake(struct game *game) {
    int x = game->snake.x[0];
    int y = game->snake.y[0];
    switch (game->snake.direction) {
        case UP:
            y--;
            break;
        case DOWN:
            y++;
            break;
        case LEFT:
            x--;
            break;
        case RIGHT:
            x++;
            break;
    }
    int head_index = (game->snake.length - 1) % SNAKE_SIZE;
    game->snake.x[head_index] = x;
    game->snake.y[head_index] = y;
}

void update_game(struct game *game) {
    draw_board(game);
    draw_snake(game);
    move_snake(game);
    if (game->snake.x[0] == game->fruit.x && game->snake.y[0] == game->fruit.y) {
        game->score++;
        game->snake.length++;
        game->fruit.x = rand() % (BOARD_SIZE - 2) + 1;
        game->fruit.y = rand() % (BOARD_SIZE - 2) + 1;
    } else {
        int tail_index = (game->snake.length - 2) % SNAKE_SIZE;
        game->snake.x[game->snake.length - 1] = game->snake.x[tail_index];
        game->snake.y[game->snake.length - 1] = game->snake.y[tail_index];
    }
    if (game->snake.x[0] < 0 || game->snake.x[0] >= BOARD_SIZE || game->snake.y[0] < 0 || game->snake.y[0] >= BOARD_SIZE) {
        game->is_over = 1;
    } else {
        int i;
        for (i = 1; I < game->snake.length; i++) {
            if (game->snake.x[0] == game->snake.x[i] && game->snake.y[0] == game->snake.y[i]) {
                game->is_over = 1;
                break;
            }
        }
    }
}

int main() {
    initgame();
    struct game game;
    init_game(&game);
    int ch;
    while (!game.is_over) {
        update_game(&game);
        delay(100);
        ch = getch();
        switch (ch) {
            case 'a':
